const {chromium}=require('playwright'),fs=require('node:fs/promises'),http=require('node:http'),assert=require('node:assert/strict');
(async()=>{
 const {renderApp}=await import('../src/ui.mjs'),{action,summary,settle,CATALOG}=await import('../src/engine.mjs');
 const loader=await fs.readFile('coco-bank-private-v1.js','utf8');const now=Date.now();let state=null,calls=0;
 const market={prices:Object.fromEntries(CATALOG.map(c=>[c.id,{eur:c.id==='BTC'?70000:100,local:100,currency:'EUR',at:now-3600000,fetchedAt:now,source:'test fixture'}])),rate:{annualPct:2.441,date:new Date(now-86400000).toISOString().slice(0,10),fetchedAt:now,source:'test fixture'},events:[],updatedAt:now,errors:[]};
 const payload=()=>({state,summary:state?summary(state,market,now):null,market,serverTime:now,catalog:CATALOG});
 const server=http.createServer((req,res)=>{res.setHeader('Content-Type','text/html');res.end(`<html><body><div id="cocoApp" class="cocoVistaJugador"><h1>Francesco</h1><section class="panelJugador" aria-label="Mis retos"></section></div><script>window.__session={user:{id:'88c250d6-3f3c-4e82-95ea-951dd914949d'},access_token:'local-test-token'};window.__COCO_SUPABASE_CLIENT={auth:{getSession:async()=>({data:{session:window.__session}}),onAuthStateChange:fn=>{window.__authCallback=fn}}};</script><script>${loader}</script></body></html>`)});await new Promise(r=>server.listen(0,'127.0.0.1',r));
 const browser=await chromium.launch({headless:true,executablePath:process.env.COCO_CHROMIUM_PATH||undefined,args:['--no-sandbox','--disable-dev-shm-usage']}),page=await browser.newPage({viewport:{width:1360,height:1000}}),errors=[];
 page.on('pageerror',e=>errors.push(e.message));
 await page.route('https://coco-bank-private.chatinmobiliario.workers.dev/**',async route=>{calls++;const req=route.request(),path=new URL(req.url()).pathname;let status=200,body,type='application/json';try{if(path==='/access')body={allowed:true};if(path==='/bundle'){body=renderApp();type='text/html'}if(path==='/state')body=payload();if(path==='/action'){state=action(state,market,req.postDataJSON(),now);body=payload()}}catch(e){status=400;body={error:e.message}}await route.fulfill({status,contentType:type,headers:{'Access-Control-Allow-Origin':'*'},body:typeof body==='string'?body:JSON.stringify(body)})});
 await page.goto('http://127.0.0.1:'+server.address().port);await page.getByRole('button',{name:'Entrar en Coco Bank'}).click();const app=page.frameLocator('iframe');
 await app.getByRole('button',{name:'Crear mi primer desafío'}).click();await app.getByRole('button',{name:'Crear mi desafío',exact:false}).click();
 await app.getByRole('button',{name:'Reiniciar y configurar otro desafío'}).waitFor();await app.locator('[data-tab="home"]').first().click();await app.getByText('160 CB',{exact:true}).waitFor();await page.screenshot({path:(process.env.COCO_TEST_OUTPUT||'/tmp')+'/bank-desktop.png',fullPage:true});
 await app.getByRole('button',{name:'Mi vida',exact:false}).first().click();await app.getByRole('button',{name:'Pagar',exact:true}).first().click();await app.getByText('Pagado ✓',{exact:true}).waitFor();assert.equal(state.bills.filter(b=>b.paid).length,1);
 await app.getByRole('button',{name:'Invertir',exact:false}).first().click();await app.locator('[data-lesson="AAPL"]').click();await app.getByRole('button',{name:'No. Su acción también puede bajar.'}).click();await app.locator('[data-lesson="AAPL"]').filter({hasText:'Ficha aprendida'}).waitFor();await app.locator('[data-buy="AAPL"]').click();await app.locator('input[name="amount"]').fill('5');await app.getByRole('button',{name:'Dejar orden de compra',exact:true}).click();await app.getByText('Comprar AAPL',{exact:false}).waitFor();assert.equal(state.orders.length,1);
 await page.setViewportSize({width:390,height:844});await app.locator('[data-tab="home"]').first().click();await page.screenshot({path:(process.env.COCO_TEST_OUTPUT||'/tmp')+'/bank-mobile.png',fullPage:true});assert.equal(await app.locator('html').evaluate(el=>el.scrollWidth<=innerWidth),true);
 await page.evaluate(()=>{window.__session=null;window.__authCallback('SIGNED_OUT',null)});await page.locator('iframe').waitFor({state:'detached'});assert.equal(await page.locator('[data-coco-bank-entry]').count(),0);
 const before=calls;await page.evaluate(()=>{window.__session={user:{id:'another-user'},access_token:'other-token'};window.__authCallback('SIGNED_IN',window.__session)});await page.waitForTimeout(150);assert.equal(calls,before);assert.equal(await page.locator('[data-coco-bank-entry]').count(),0);
 assert.deepEqual(errors,[]);console.log(JSON.stringify({ok:true,checks:['Francesco entry','parent configuration','monthly bill payment','lesson unlock','queued order','mobile overflow','logout cleanup','other user hidden'],calls}));await browser.close();server.close();
})().catch(e=>{console.error(e);process.exit(1)});
